import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u08")
C = "B1-B2"
# Lições de aprofundamento (10–25): palavras parecidas e nuances.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)
def N(id, nl, pt, art, pl=None): return V(id, nl, pt, "noun", art, pl)

L(10, "Pôr: zetten, leggen, hangen, stoppen", "Zet de fles neer, leg het boek weg.",
  ["Escolher o verbo de «pôr» certo segundo a posição final"],
  vocab=[X("v-neerzetten","neerzetten","pousar (de pé)","verb"), X("v-stoppen-in","stoppen in","meter em|enfiar em","verb"),
         X("v-plaatsen","plaatsen","colocar (formal)","verb")],
  ex=[("Zet de fles maar op tafel.","Põe a garrafa em cima da mesa."),("Leg het boek op het bed.","Põe o livro em cima da cama."),("Stop je telefoon in je tas.","Mete o telemóvel na mala."),("De gemeente plaatst nieuwe bankjes.","A câmara coloca bancos novos.")],
  review=["v-zetten-leggen","v-ophangen"],
  gram=[G("g-zetten-leggen-2","Que verbo de «pôr»?","Depende da posição final do objeto: **zetten** = fica **de pé** (fles, stoel, glas); **leggen** = fica **deitado** (boek, telefoon, sleutels); **hangen/ophangen** = fica **pendurado** (jas, schilderij); **stoppen in** = fica **dentro** de algo (tas, zak). **Plaatsen** é formal e neutro.",
    [("Hang je jas aan de kapstok.","Pendura o casaco no bengaleiro."),("Ik stop het geld in mijn portemonnee.","Meto o dinheiro na carteira.")])],
  cefr=C, exs=[
    MA([("neerzetten","pousar de pé"),("stoppen in","meter em"),("plaatsen","colocar (formal)"),("ophangen","pendurar")], "Pôr.", ["v-neerzetten","v-stoppen-in","v-plaatsen","v-ophangen"]),
    MC("___ de wijnglazen op tafel.", ["*Zet","Leg|Os copos ficam de pé.","Hang|Não."], "De pé → zetten.", ["v-zetten-leggen"]),
    MC("___ de sleutels op het kastje.", ["*Leg","Zet|As chaves ficam deitadas.","Stop|Não estão dentro."], "Deitado → leggen.", ["v-zetten-leggen"]),
    MC("___ je handschoenen in je zak.", ["*Stop","Leg|Ficam dentro.","Zet|Não."], "Dentro → stoppen in.", ["v-stoppen-in"]),
    TR("pt-nl","Mete o telemóvel na mala.", ["Stop je telefoon in je tas","Stop je mobiel in je tas"], "stoppen in.", ["v-stoppen-in"]),
    TR("pt-nl","Pousa a mala ali.", ["Zet de tas daar neer","Zet je tas daar neer"], "neerzetten.", ["v-neerzetten"]),
    FB("Ik heb de lamp op het bureau ___.", ["gezet"], "Candeeiro de pé → zetten.", ["v-zetten-leggen"], choices=["gezet","gelegd","gestopt"], tr="Pus o candeeiro em cima da secretária."),
    FE(["Leg","de","stoel","bij","het","raam."], 0, "Zet", "Cadeira fica de pé: zetten.", ["v-zetten-leggen"]),
    LI("De gemeente plaatst dit jaar honderd nieuwe fietsenrekken.", ["De gemeente plaatst dit jaar honderd nieuwe fietsenrekken","De gemeente plaatst dit jaar 100 nieuwe fietsenrekken"], "A câmara coloca este ano cem novos suportes para bicicletas.", "Formal.", ["v-plaatsen"]),
  ], diff=4, mins=6)

L(11, "Brengen, halen, nemen", "Ik breng de kinderen, jij haalt ze op.",
  ["Distinguir levar, ir buscar e tirar/levar consigo"],
  vocab=[X("v-brengen","brengen","levar (a algum lado)|trazer","verb"), X("v-halen","halen","ir buscar","verb")],
  ex=[("Ik breng de kinderen naar school.","Eu levo as crianças à escola."),("Jij haalt ze om drie uur op.","Tu vais buscá-las às três."),("Ik haal even brood.","Vou só buscar pão."),("Neem een paraplu mee!","Leva um guarda-chuva!")],
  review=["v-meenemen","v-ophalen"],
  gram=[G("g-brengen-halen","Brengen, halen, (mee)nemen","**Brengen** = levar algo/alguém **de onde estou para outro sítio** (ou trazer para onde está o outro). **Halen/ophalen** = **ir buscar** e voltar com isso. **Meenemen** = levar **comigo** quando vou. **Nemen** = tirar/pegar ou apanhar (transporte).",
    [("Kun je me naar het station brengen?","Podes levar-me à estação?"),("Ik neem de trein.","Apanho o comboio.")])],
  cefr=C, exs=[
    MA([("brengen","levar"),("halen","ir buscar"),("meenemen","levar consigo"),("ophalen","ir buscar (alguém/algo)")], "Movimento.", ["v-brengen","v-halen","v-meenemen","v-ophalen"]),
    MC("Vais à padaria e voltas com pão: «Ik ___ brood.»", ["*haal","breng|Não levas pão para lá.","neem mee|Não."], "Ir buscar.", ["v-halen"]),
    MC("Vais a casa de amigos e levas vinho: «Ik ___ wijn mee.»", ["*neem","haal|Não.","breng|Possível sem «mee», mas aqui é «neem mee»."], "Levar consigo.", ["v-meenemen"]),
    TR("pt-nl","Eu levo as crianças à escola.", ["Ik breng de kinderen naar school"], "brengen.", ["v-brengen"]),
    TR("pt-nl","Vou buscar-te à estação.", ["Ik haal je op van het station","Ik haal je op bij het station","Ik kom je ophalen van het station"], "ophalen.", ["v-ophalen"]),
    FB("Kun je me morgen naar het vliegveld ___?", ["brengen"], "Levar.", ["v-brengen"], choices=["brengen","halen","nemen"], tr="Podes levar-me amanhã ao aeroporto?"),
    FE(["Ik","breng","je","om","vijf","uur","op","van","je","werk."], 1, "haal", "Ir buscar: ophalen.", ["v-halen"]),
    LI("Wil jij straks even boodschappen halen?", ["Wil jij straks even boodschappen halen","Wil jij straks even boodschappen halen?","Wil je straks even boodschappen halen"], "Queres ir buscar as compras daqui a pouco?", "halen.", ["v-halen"]),
    WO("Vou buscar pão.", ["Ik","haal","brood"], "Ordem.", ["v-halen"]),
  ], diff=4, mins=6)

