L(19, "Arrendar e alugar", "Wij verhuren fietsen.",
  ["Distinguir huren (tomar de aluguer) e verhuren (dar de aluguer)"],
  vocab=[X("v-verhuren","verhuren","arrendar|alugar (a alguém)","verb"), X("v-leasen","leasen","fazer leasing","verb")],
  ex=[("Ik huur een fiets voor een dag.","Alugo uma bicicleta por um dia."),("Deze winkel verhuurt fietsen.","Esta loja aluga bicicletas."),("Veel bedrijven leasen auto's.","Muitas empresas fazem leasing de carros."),("De huurder betaalt de huur.","O inquilino paga a renda.")],
  review=["v-huurder","v-huren","v-verhuurder","v-onderhuren"],
  cefr=C, exs=[
    MA([("huren","tomar de aluguer"),("verhuren","dar de aluguer"),("huurder","inquilino"),("verhuurder","senhorio")], "Aluguer.", ["v-huren","v-verhuren","v-huurder","v-verhuurder"]),
    MC("O dono do apartamento ___ het appartement aan een student.", ["*verhuurt","huurt|É o estudante que huurt.","leent|Não."], "Dar de aluguer.", ["v-verhuren"]),
    MC("Placa numa loja: «Fietsverhuur» significa…", ["*aluguer de bicicletas","venda de bicicletas|Não.","reparação|Não."], "Composto.", ["v-verhuren"]),
    TR("pt-nl","Esta loja aluga bicicletas.", ["Deze winkel verhuurt fietsen"], "verhuren.", ["v-verhuren"]),
    TR("pt-nl","Alugo um carro por uma semana.", ["Ik huur een auto voor een week","Ik huur voor een week een auto"], "huren.", ["v-huren"]),
    FB("De ___ moet het appartement schoon achterlaten.", ["huurder"], "Inquilino.", ["v-huurder"], choices=["huurder","verhuurder","eigenaar"], tr="O inquilino tem de deixar o apartamento limpo."),
    FE(["Ik","verhuur","een","fiets","bij","het","station","voor","mijn","vakantie."], 1, "huur", "Tomar de aluguer: huren.", ["v-huren"]),
    LI("Mag ik mijn kamer onderverhuren als ik op reis ben?", ["Mag ik mijn kamer onderverhuren als ik op reis ben","Mag ik mijn kamer onderverhuren als ik op reis ben?"], "Posso subarrendar o meu quarto quando estou em viagem?", "Pergunta (verifique sempre o contrato).", ["v-onderhuren"]),
    WO("Alugamos bicicletas.", ["Wij","verhuren","fietsen"], "Ordem.", ["v-verhuren"]),
  ], diff=3, mins=5)

L(20, "Certeza: zeker, beslist, vast, stellig", "Hij komt vast wel.",
  ["Distinguir advérbios de certeza"],
  vocab=[X("v-vast-wel","vast wel","de certeza (suposição)|com certeza"), X("v-beslist","beslist","decididamente|sem dúvida","adverb"),
         X("v-stellig","stellig","categoricamente","adverb")],
  ex=[("Hij komt vast wel, hij is altijd op tijd.","Ele vem de certeza, está sempre a horas."),("Dat is beslist de beste oplossing.","Essa é sem dúvida a melhor solução."),("Ze ontkende het stellig.","Ela negou-o categoricamente.")],
  review=["v-zeker","v-zeker-weten","v-ongetwijfeld"],
  cefr=C, exs=[
    MA([("vast wel","de certeza (suponho)"),("beslist","sem dúvida"),("stellig","categoricamente"),("zeker","certamente")], "Certeza.", ["v-vast-wel","v-beslist","v-stellig","v-zeker"]),
    MC("«Ze is vast moe» exprime…", ["*uma suposição forte","um facto verificado|Não.","uma ordem|Não."], "vast = suposição.", ["v-vast-wel"]),
    MC("«Ik ben het er stellig mee oneens» — a pessoa discorda…", ["*categoricamente","um pouco|Não.","em segredo|Não."], "Intensidade.", ["v-stellig"]),
    TR("pt-nl","Ele vem de certeza.", ["Hij komt vast wel","Hij komt zeker","Hij komt beslist"], "vast wel.", ["v-vast-wel"]),
    TR("pt-nl","Essa é sem dúvida a melhor solução.", ["Dat is beslist de beste oplossing","Dat is zeker de beste oplossing","Dat is ongetwijfeld de beste oplossing"], "beslist.", ["v-beslist"]),
    FB("Je vindt het ___ wel leuk; jij houdt van musea.", ["vast"], "Suposição.", ["v-vast-wel"], choices=["vast","stellig","beslist"], tr="De certeza que vais gostar; tu adoras museus."),
    FE(["Ze","ontkende","het","stellige."], 3, "stellig.", "Advérbio: sem -e.", ["v-stellig"]),
    LI("Dat moet je beslist eens proberen!", ["Dat moet je beslist eens proberen","Dat moet je beslist eens proberen!"], "Tens mesmo de experimentar isso!", "Recomendação forte.", ["v-beslist"]),
    WO("Ele vem de certeza.", ["Hij","komt","vast","wel"], "Ordem.", ["v-vast-wel"]),
  ], diff=4, mins=5)

